void mergeSort(int[] a, int lo, int hi) {
    if (lo >= hi) return;
    int mid = (lo + hi) / 2;
    mergeSort(a, lo, mid);          // sort the left half
    mergeSort(a, mid + 1, hi);      // sort the right half
    merge(a, lo, mid, hi);          // combine the two halves
}

